	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !authenticate(r) || !authorize(r) || !validInput(r) {
			http.Error(w, "denied", http.StatusForbidden)
			return
		}
		audit(r)
		next.ServeHTTP(w, r)   // business handler: no security code
	})
}

